import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { itensCardapioAPI } from '../services/api';
import { Trash2, Edit2 } from 'lucide-react';

const ItemCardapioList: React.FC = () => {
  const [itens, setItens] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchItens = async () => {
      try {
        setLoading(true);
        const response = await itensCardapioAPI.listar();
        setItens(response.data);
      } catch (err) {
        setError('Erro ao carregar itens do cardápio');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchItens();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este item do cardápio?')) {
      try {
        await itensCardapioAPI.deletar(id);
        setItens(itens.filter(item => item.idItemc !== id));
      } catch (err) {
        setError('Erro ao excluir item do cardápio');
        console.error(err);
      }
    }
  };

  if (loading) return <div className="text-center py-10">Carregando...</div>;
  if (error) return <div className="text-center text-red-500 py-10">{error}</div>;

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800">Itens do Cardápio</h1>
        <Link to="/itens-cardapio/novo" className="bg-indigo-600 text-white px-4 py-2 rounded-md hover:bg-indigo-700 transition-colors">
          Novo Item
        </Link>
      </div>

      {itens.length === 0 ? (
        <div className="text-center py-10 text-gray-500">
          Nenhum item do cardápio cadastrado.
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nome</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Descrição</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Preço</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Disponibilidade</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {itens.map((item) => (
                <tr key={item.idItemc} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{item.dscNomeItemc}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{item.dscInformacaoItemc || '-'}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">R$ {parseFloat(item.valPrecoItemc).toFixed(2)}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    <span className={`${item.dscDisponibilidadeItemc === 'disponivel' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'} px-2 py-1 rounded-full text-xs`}>
                      {item.dscDisponibilidadeItemc === 'disponivel' ? 'Disponível' : 'Esgotado'}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 flex space-x-2">
                    <Link to={`/itens-cardapio/${item.idItemc}/editar`} className="text-indigo-600 hover:text-indigo-900">
                      <Edit2 className="h-4 w-4" />
                    </Link>
                    <button onClick={() => handleDelete(item.idItemc)} className="text-red-600 hover:text-red-900">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default ItemCardapioList;
